/// ### Accounts:
///
///   0. `[writable]` genesis_account
///   1. `[writable]` bucket
///   2. `[writable]` bucket_token_account
///   3. `[writable]` distribution
///   4. `[writable]` distribution_token_account
///   5. `[]` mint
///   6. `[writable, signer]` payer
///   7. `[signer, optional]` authority
///   8. `[writable]` distro_fee_wallet
///   9. `[]` distro_program
///   10. `[]` associated_token_program
///   11. `[writable]` fee_wallet
///   12. `[]` token_program
///   13. `[]` system_program
///   14. `[signer, optional]` backend_signer
pub struct FundDistributionV1CpiBuilder<'a, 'b> {
    instruction: Box<FundDistributionV1CpiBuilderInstruction<'a, 'b>>,
}

impl<'a, 'b> FundDistributionV1CpiBuilder<'a, 'b> {
    pub fn new(program: &'b solana_program::account_info::AccountInfo<'a>) -> Self {
        let instruction = Box::new(FundDistributionV1CpiBuilderInstruction {
            __program: program,
            genesis_account: None,
            bucket: None,
            bucket_token_account: None,
            distribution: None,
            distribution_token_account: None,
            mint: None,
            payer: None,
            authority: None,
            distro_fee_wallet: None,
            distro_program: None,
            associated_token_program: None,
            fee_wallet: None,
            token_program: None,
            system_program: None,
            backend_signer: None,
            index: None,
            padding: None,
            __remaining_accounts: Vec::new(),
        });
        Self { instruction }
    }
    /// The address of the genesis account
    #[inline(always)]
    pub fn genesis_account(
        &mut self,
        genesis_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.genesis_account = Some(genesis_account);
        self
    }
    /// The address of the bucket account
    #[inline(always)]
    pub fn bucket(
        &mut self,
        bucket: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.bucket = Some(bucket);
        self
    }
    /// The token account owned by the bucket
    #[inline(always)]
    pub fn bucket_token_account(
        &mut self,
        bucket_token_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.bucket_token_account = Some(bucket_token_account);
        self
    }
    /// The distribution address
    #[inline(always)]
    pub fn distribution(
        &mut self,
        distribution: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.distribution = Some(distribution);
        self
    }
    /// The token account owned by the distribution
    #[inline(always)]
    pub fn distribution_token_account(
        &mut self,
        distribution_token_account: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.distribution_token_account = Some(distribution_token_account);
        self
    }
    /// The address of the mint account
    #[inline(always)]
    pub fn mint(&mut self, mint: &'b solana_program::account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.mint = Some(mint);
        self
    }
    /// The account paying for the storage fees
    #[inline(always)]
    pub fn payer(&mut self, payer: &'b solana_program::account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.payer = Some(payer);
        self
    }
    /// `[optional account]`
    /// The authority of the mint
    #[inline(always)]
    pub fn authority(
        &mut self,
        authority: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    ) -> &mut Self {
        self.instruction.authority = authority;
        self
    }
    /// The wallet where distro fees are sent
    #[inline(always)]
    pub fn distro_fee_wallet(
        &mut self,
        distro_fee_wallet: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.distro_fee_wallet = Some(distro_fee_wallet);
        self
    }
    /// The mpl-distro program
    #[inline(always)]
    pub fn distro_program(
        &mut self,
        distro_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.distro_program = Some(distro_program);
        self
    }
    /// The associated token program
    #[inline(always)]
    pub fn associated_token_program(
        &mut self,
        associated_token_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.associated_token_program = Some(associated_token_program);
        self
    }
    /// The wallet where fees are sent
    #[inline(always)]
    pub fn fee_wallet(
        &mut self,
        fee_wallet: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.fee_wallet = Some(fee_wallet);
        self
    }
    /// The SPL Token program
    #[inline(always)]
    pub fn token_program(
        &mut self,
        token_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_program = Some(token_program);
        self
    }
    /// The system program
    #[inline(always)]
    pub fn system_program(
        &mut self,
        system_program: &'b solana_program::account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.system_program = Some(system_program);
        self
    }
    /// `[optional account]`
    /// Backend authorisation signer
    #[inline(always)]
    pub fn backend_signer(
        &mut self,
        backend_signer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    ) -> &mut Self {
        self.instruction.backend_signer = backend_signer;
        self
    }
    #[inline(always)]
    pub fn index(&mut self, index: u8) -> &mut Self {
        self.instruction.index = Some(index);
        self
    }
    #[inline(always)]
    pub fn padding(&mut self, padding: [u8; 6]) -> &mut Self {
        self.instruction.padding = Some(padding);
        self
    }
    /// Add an additional account to the instruction.
    #[inline(always)]
    pub fn add_remaining_account(
        &mut self,
        account: &'b solana_program::account_info::AccountInfo<'a>,
        is_writable: bool,
        is_signer: bool,
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .push((account, is_writable, is_signer));
        self
    }
    /// Add additional accounts to the instruction.
    ///
    /// Each account is represented by a tuple of the `AccountInfo`, a `bool` indicating whether the account is writable or not,
    /// and a `bool` indicating whether the account is a signer or not.
    #[inline(always)]
    pub fn add_remaining_accounts(
        &mut self,
        accounts: &[(
            &'b solana_program::account_info::AccountInfo<'a>,
            bool,
            bool,
        )],
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .extend_from_slice(accounts);
        self
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed(&[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed(
        &self,
        signers_seeds: &[&[&[u8]]],
    ) -> solana_program::entrypoint::ProgramResult {
        let args = FundDistributionV1InstructionArgs {
            index: self.instruction.index.clone().expect("index is not set"),
            padding: self
                .instruction
                .padding
                .clone()
                .expect("padding is not set"),
        };
        let instruction = FundDistributionV1Cpi {
            __program: self.instruction.__program,

            genesis_account: self
                .instruction
                .genesis_account
                .expect("genesis_account is not set"),

            bucket: self.instruction.bucket.expect("bucket is not set"),

            bucket_token_account: self
                .instruction
                .bucket_token_account
                .expect("bucket_token_account is not set"),

            distribution: self
                .instruction
                .distribution
                .expect("distribution is not set"),

            distribution_token_account: self
                .instruction
                .distribution_token_account
                .expect("distribution_token_account is not set"),

            mint: self.instruction.mint.expect("mint is not set"),

            payer: self.instruction.payer.expect("payer is not set"),

            authority: self.instruction.authority,

            distro_fee_wallet: self
                .instruction
                .distro_fee_wallet
                .expect("distro_fee_wallet is not set"),

            distro_program: self
                .instruction
                .distro_program
                .expect("distro_program is not set"),

            associated_token_program: self
                .instruction
                .associated_token_program
                .expect("associated_token_program is not set"),

            fee_wallet: self.instruction.fee_wallet.expect("fee_wallet is not set"),

            token_program: self
                .instruction
                .token_program
                .expect("token_program is not set"),

            system_program: self
                .instruction
                .system_program
                .expect("system_program is not set"),

            backend_signer: self.instruction.backend_signer,
            __args: args,
        };
        instruction.invoke_signed_with_remaining_accounts(
            signers_seeds,
            &self.instruction.__remaining_accounts,
        )
    }
}

struct FundDistributionV1CpiBuilderInstruction<'a, 'b> {
    __program: &'b solana_program::account_info::AccountInfo<'a>,
    genesis_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    bucket: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    bucket_token_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    distribution: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    distribution_token_account: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    mint: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    payer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    authority: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    distro_fee_wallet: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    distro_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    associated_token_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    fee_wallet: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    token_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    system_program: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    backend_signer: Option<&'b solana_program::account_info::AccountInfo<'a>>,
    index: Option<u8>,
    padding: Option<[u8; 6]>,
    /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
    __remaining_accounts: Vec<(
        &'b solana_program::account_info::AccountInfo<'a>,
        bool,
        bool,
    )>,
}
